// CERT Skills Practice Test 2. Original questions written for Valus from the HOSA 2026–27 test plan,
// slightly harder than the sample items: preparedness, ICS, SALT triage, bleeding control, medical operations,
// disaster psychology, fire safety, search and rescue and terrorism not covered in Practice Test 1.
import {q, mix} from './q.js';
const CERT='FEMA CERT Basic Training Participant Manual / IS-317', FAST='American Red Cross, First Aid for Severe Trauma (FAST)', SALT='SALT Mass Casualty Triage (NDLSF)';
const PREP='Disaster Preparedness', ORG='CERT Organization', LTI='Life Threatening Interventions and SALT Triage', MED='Medical Operations', PSY='Disaster Psychology', FIRE='Fire Safety', SAR='Light Search and Rescue Operations', TER='Terrorism';

export default {
 id:'cert-skills-2',
 event:'CERT Skills',
 title:'Practice Test 2',
 subtitle:'Full-length Round One simulation',
 minutes:60,
 sources:'the FEMA CERT Basic Training Participant Manual (IS-317), American Red Cross FAST and SALT Mass Casualty Triage',
 plan:[{area:PREP,weight:15},{area:ORG,weight:5},{area:LTI,weight:30},{area:MED,weight:20},{area:PSY,weight:5},{area:FIRE,weight:5},{area:SAR,weight:15},{area:TER,weight:5}],
 questions:mix([
  q(PREP,'How many days of supplies does FEMA recommend in a basic home disaster kit?','At least 3 days',['Exactly 1 day','About 6 hours','At least 30 days'],'A','Kits should include water, food, a radio, a flashlight, first aid supplies and medications.',CERT),
  q(PREP,'Which type of radio is recommended for receiving emergency alerts when power is out?','A NOAA weather radio',['A two-way CB radio','A car stereo only','A Bluetooth speaker'],'B','Battery or hand-crank NOAA radios broadcast official warnings 24 hours a day.',CERT),
  q(PREP,'What is the difference between a tornado watch and a tornado warning?','A warning means a tornado is seen or on radar',['A watch means a tornado is on the ground','They mean exactly the same thing','A warning is issued days in advance'],'B','A watch means conditions are favorable; a warning means take shelter now.',CERT),
  q(PREP,'What is the safest action if caught outside during a lightning storm with no shelter?','Avoid tall objects and open fields',['Stand under a tall, lone tree','Hold a metal pole for safety','Lie flat on wet open ground'],'C','Get inside a building or hard-topped car as soon as possible.',CERT),
  q(PREP,'Which item should NOT be used for lighting after a disaster because of gas leak risk?','Candles',['Flashlights','Glow sticks','Battery lanterns'],'D','Open flames can ignite leaking gas; use battery-powered lights instead.',CERT),
  q(PREP,'Which is a key step in preparing for a wildfire?','Clear brush around the home',['Store firewood by the house','Open all windows when leaving','Leave lawn furniture by walls'],'A','Creating defensible space slows fire spread toward buildings.',CERT),
  q(PREP,'What should you do with food from a refrigerator after a power outage longer than 4 hours?','Throw out perishable foods',['Refreeze all of it later','Cook it all at once','Keep it for one week'],'B','When in doubt, throw it out; spoiled food can cause serious illness.',CERT),
  q(PREP,'During a hurricane, why should you stay inside even when the wind suddenly stops?','The eye may be passing over',['The storm has fully ended','Floodwater is safe then','Power lines are turned off'],'C','Winds return quickly from the opposite direction after the eye passes.',CERT),
  q(ORG,'In ICS, who is responsible for overall management of the incident?','Incident Commander',['Logistics Chief','Planning Chief','Finance Chief'],'D','The IC sets objectives and may assign others to command staff and general staff roles.',CERT),
  q(ORG,'Which ICS section is responsible for supplies, food and equipment?','Logistics',['Operations','Planning','Finance'],'A','Operations carries out tactics; Planning tracks resources and develops the plan.',CERT),
  q(ORG,'What should a CERT member do before self-deploying after a disaster?','Make sure own family is safe',['Go straight to the worst damage','Wait for a news crew to arrive','Drive into flooded areas to help'],'B','CERT members help others only after their own homes and families are safe.',CERT),
  q(LTI,'In SALT, which patients are asked to walk to a designated area during the global sort?','Those who can walk',['Those not breathing','Those with severe bleeding','Those who are unconscious'],'C','Walkers are assessed last because they are likely the least injured.',SALT),
  q(LTI,'In SALT, what is assessed second during the global sort?','Those who wave or move',['Those who walk to the area','Those who are already dead','Those with only minor cuts'],'D','Those who are still and do not move are assessed first for life threats.',SALT),
  q(LTI,'In SALT, a patient who does not obey commands but is breathing after interventions is categorized as:','Immediate',['Minimal','Delayed','Dead'],'A','Immediate patients are likely to survive with prompt care and transport.',SALT),
  q(LTI,'Which SALT category is shown with a red tag?','Immediate',['Delayed','Minimal','Expectant'],'B','Yellow is delayed, green is minimal, gray is expectant and black is dead.',SALT),
  q(LTI,'In SALT, which intervention may be done for a patient with a tension pneumothorax if trained?','Chest decompression',['Splinting a leg','Taking a history','Giving a drink'],'C','Lifesaving interventions are quick and do not require staying with the patient.',SALT),
  q(LTI,'What is the correct tightness for a tourniquet?','Until the bleeding stops',['Just snug enough to stay in place','Loose enough to fit two fingers','Tight only until the victim cries'],'D','Note the time it was applied and do not loosen it once placed.',FAST),
  q(LTI,'How far above a bleeding wound should a tourniquet be placed if the exact site is unclear?','High and tight on the limb',['Directly over a joint','Below the wound','Around the neck'],'A','If the wound site is unknown, place it as high on the limb as possible.',FAST),
  q(LTI,'What should be done if one tourniquet does not stop the bleeding?','Apply a second one above the first',['Remove the first one right away','Loosen it and wait 10 minutes','Apply ice to the wound instead'],'B','A second tourniquet placed just above the first often controls the bleeding.',FAST),
  q(LTI,'Which material is best for packing a deep wound?','Gauze',['Paper towels','Cotton balls','Plastic wrap'],'C','Pack the wound tightly and hold firm pressure for at least 3 minutes.',FAST),
  q(LTI,'Which respiratory rate in an adult suggests a need for immediate treatment in CERT triage?','Above 30 per minute',['About 12 per minute','About 16 per minute','About 20 per minute'],'D','CERT uses rapid breathing over 30 per minute as a sign of shock.',CERT),
  q(LTI,'How long should a capillary refill (blanch test) take in a healthy person?','2 seconds or less',['About 5 seconds','About 10 seconds','At least 30 seconds'],'A','A longer refill time suggests poor circulation and possible shock.',CERT),
  q(LTI,'Why should CERT members avoid giving food or water to a victim in shock?','The victim may vomit',['Food speeds up the shock','Water causes bleeding','It is against the law'],'B','Keep the victim warm, lying down and monitored until help arrives.',CERT),
  q(LTI,'Which item must be checked for obvious life threats during the SALT individual assessment?','Severe bleeding',['Old healed scars','Hair color','Shoe size'],'C','Life threats include major bleeding, airway problems and shock.',SALT),
  q(LTI,'In SALT, a patient is breathing, follows commands and has minor injuries. Which category applies?','Minimal',['Immediate','Delayed','Expectant'],'D','Minimal (green) patients can wait for care and may even help with other victims.',SALT),
  q(LTI,'Which hand position is used to apply direct pressure to a wound?','Firm, steady palm pressure',['Light taps with fingertips','Pinching the skin gently','Rubbing the wound in circles'],'A','Use gloves and a dressing; press hard and do not lift to check.',FAST),
  q(MED,'Which body area should be checked first in a head-to-toe assessment?','Head',['Feet','Arms','Back'],'B','Assess the head, neck, shoulders, chest, arms, abdomen, pelvis and legs in order.',CERT),
  q(MED,'Which sign suggests a closed head injury?','Unequal pupils',['Equal pupils','Warm hands','Normal speech'],'C','Other signs include confusion, vomiting and fluid from the ears or nose.',CERT),
  q(MED,'What should be done for a victim with a suspected fracture and no pulse below it?','Report it for urgent care',['Walk the victim to a parked car','Massage the limb hard','Bend the limb back slowly'],'D','A missing pulse below an injury suggests poor blood flow, which is urgent.',CERT),
  q(MED,'How should a partial-thickness burn with blisters be treated?','Cool with water and cover loosely',['Pop the blisters and apply butter','Apply ice directly for an hour','Rub the area with alcohol'],'A','Cool the burn with clean water, do not break blisters, and cover with clean, dry dressings.',CERT),
  q(MED,'Which is the best way to purify water when boiling is possible?','Boil it for 1 minute',['Let it sit in the sun','Strain it through a sock','Add table salt to it'],'B','Boiling kills most germs; let the water cool before drinking.',CERT),
  q(MED,'Where should the CERT medical treatment area be located?','Away from hazards, easy to reach',['Next to the damaged building','In a low, flood-prone area','On a busy street corner'],'C','The area should be upwind, uphill and accessible to vehicles.',CERT),
  q(MED,'Which items should CERT members wear to protect against bloodborne pathogens?','Gloves, mask and goggles',['Shorts and sandals only at all times','No gear at all','Only a hard hat'],'D','Change gloves between victims and wash hands when possible to avoid spreading infection.',CERT),
  q(MED,'Which approach is used for a victim with a suspected spinal injury who must be moved?','Keep the head, neck and spine in line',['Roll the victim face down quickly','Lift the victim by the arms only','Bend the neck to open the airway'],'A','Move the victim only if they are in danger, using a backboard if possible.',CERT),
  q(MED,'Which item is used to support an injured arm after splinting?','A sling',['A tourniquet','A neck brace','A cold pack only'],'B','A sling keeps the arm close to the body and reduces movement and pain.',CERT),
  q(MED,'Which sign suggests hypothermia is getting worse?','Shivering stops, confusion grows',['Shivering gets much stronger','Skin becomes warm','The pulse speeds up'],'C','Move the victim to a warm place, remove wet clothing and wrap them in dry blankets.',CERT),
  q(PSY,'Which is a common physical reaction to disaster stress?','Trouble sleeping',['Improved appetite','More energy','Better memory'],'D','Stress reactions such as poor sleep are normal and usually improve over days to weeks.',CERT),
  q(PSY,'Which phrase best supports a disaster survivor?','You are safe; I am here to help',['Calm down, it could be worse','I know exactly how you feel','Do not cry about this now'],'A','Listen actively, show empathy and help survivors meet basic needs.',CERT),
  q(FIRE,'Which class of fire involves ordinary combustibles such as wood and paper?','Class A',['Class B','Class C','Class D'],'B','Class B is flammable liquids, C is electrical and D is combustible metals.',CERT),
  q(FIRE,'Before fighting a small fire, what must CERT members check?','A safe exit behind them',['The color of the smoke','The time of day','The building’s age'],'C','Always keep the exit at your back so you can escape if the fire grows.',CERT),
  q(FIRE,'What does a CERT size-up begin with?','Gathering facts',['Running into the building','Calling the media for help','Choosing a team leader'],'D','Size-up steps include assessing damage, considering probabilities and deciding on action.',CERT),
  q(SAR,'Which type of building damage means CERT members should NOT enter?','Heavy damage, such as a partial collapse',['Light damage, such as broken windows','No visible damage at all','Moderate damage with a stable frame'],'A','CERT members may enter only buildings with light or moderate damage.',CERT),
  q(SAR,'What is cribbing used for in light search and rescue?','Stabilizing lifted debris',['Marking searched rooms','Carrying victims out','Lighting dark areas'],'B','Lift an inch and crib an inch to keep debris from falling back.',CERT),
  q(SAR,'Which carry uses two rescuers and a chair to move a victim?','Chair carry',['Blanket drag','One-person arm carry','Pack-strap carry'],'C','The chair carry works well in narrow hallways and stairwells.',CERT),
  q(SAR,'What is written in the right quadrant of a CERT search marking?','Hazards found',['Team name','Date and time','Number of victims'],'D','The left is the team ID, top is date and time, and bottom is victim count.',CERT),
  q(SAR,'Which search method involves moving along the right-hand wall of each room?','Right-wall search',['The bottom-up pattern','The random pattern','The grid pattern'],'A','Following one wall helps searchers cover every room and find their way out.',CERT),
  q(SAR,'Why should CERT searchers stop and listen periodically?','To hear victims',['To rest their legs','To check the weather','To make phone calls'],'B','Teams call out, then stop and listen quietly for tapping, voices or other sounds.',CERT),
  q(SAR,'What should rescuers do if they find a victim trapped under heavy debris they cannot move safely?','Mark the location and report it',['Pull the victim out by force','Leave without telling anyone','Cut through structural walls'],'C','Professional rescuers have the equipment and training for heavy rescue.',CERT),
  q(TER,'Which sign may indicate a chemical attack?','Many people with the same symptoms',['One person with a minor cut on the arm','Sunny, clear weather','Normal bird activity nearby'],'D','Dead animals, odd odors and unexplained vapors are other warning signs.',CERT),
  q(TER,'After a possible terrorist event, what should CERT members do first?','Stay back and report it',['Collect evidence at the scene','Rush in to help everyone','Post photos online quickly'],'A','Secondary devices may target responders, so do not enter the scene.',CERT)
 ],2816)
};
